four_loops.cpp.src:
#include <iostream>

int main() {
    for (int i{1}; i <= 5; ++i) {
        std::cout << i << ' ';
    }
    std::cout << "| up\n";
    for (int i{5}; i >= 1; --i) {
        std::cout << i << ' ';
    }
    std::cout << "| down\n";
    for (int i{0}; i <= 10; i += 2) {
        std::cout << i << ' ';
    }
    std::cout << "| by twos\n";
    for (int i{10}; i < 3; ++i) {
        std::cout << i << ' ';
    }
    std::cout << "| never\n";
}

